      coreContrast: 0,
      coreHighlights: 0,
      coreShadows: 0,
      coreWhites: 0,
      coreBlacks: 0,
      coreWbMode: 'auto',
      coreTemperature: 0,
      coreTint: 0,
      // Cyan/red balance: the enlarger's C filtration.
